/// <reference types="vite/client" />
import { JLPTLevel, SubtitleLineRecord, SubtitleTokenJSON } from '../../schema/databaseSchema';

/**
 * Real timed captions generated by scripts/fetch-captions.py (one file per youtube_id).
 * Files are lazy-loaded (separate chunks) so they are not part of the main bundle.
 */
export interface CaptionLine {
  start_ms: number;
  end_ms: number;
  ja: string | null;
  th: string | null;
}

export interface CaptionFile {
  youtube_id: string;
  source: { ja: string; th: string };
  lines: CaptionLine[];
}

const loaders = import.meta.glob('./*.json') as Record<string, () => Promise<{ default: CaptionFile }>>;

// Cache of load promises keyed by youtube_id. Resolves to undefined when no file exists.
const cache = new Map<string, Promise<CaptionFile | undefined>>();

export const loadRealCaptions = (youtubeId: string): Promise<CaptionFile | undefined> => {
  let p = cache.get(youtubeId);
  if (!p) {
    const loader = loaders[`./${youtubeId}.json`];
    p = loader
      ? loader().then((m) => m.default).catch(() => undefined)
      : Promise.resolve(undefined);
    cache.set(youtubeId, p);
  }
  return p;
};

// Splits Japanese text on whitespace and punctuation. Pieces without any letters,
// digits or kana/kanji (pure punctuation) are dropped.
const splitJapanese = (text: string): string[] =>
  text
    .split(/[\s、。！？!?,.「」『』（）()［］\[\]【】…・〜~"'“”‘’:：;；]+/)
    .filter((part) => part.length > 0 && /[\p{L}\p{N}]/u.test(part));

const buildTokens = (lineId: string, ja: string, jlpt: JLPTLevel): SubtitleTokenJSON[] =>
  splitJapanese(ja).map((surface, tokenIndex) => ({
    surface,
    word_id: `${lineId}-${tokenIndex}`,
    lemma: surface,
    reading_kana: surface,
    romaji: '',
    jlpt_level: jlpt,
    part_of_speech: '',
    contextual_meaning: '',
  }));

/**
 * Builds SubtitleLineRecord[] for one video record from its loaded caption file.
 * Ids: `cap-<videoId>-<start_ms>` (suffix -2, -3 on collision within the video).
 * Thai goes only in thai_translation; natural_translation stays empty so it is not shown twice.
 * Lines without Japanese text get raw_text "" and tokens_json [].
 */
export const buildRealSubtitleLines = (
  file: CaptionFile,
  videoId: string,
  jlpt: JLPTLevel
): SubtitleLineRecord[] => {
  const used = new Map<string, number>();
  return file.lines.map((line, i) => {
    const base = `cap-${videoId}-${line.start_ms}`;
    const count = (used.get(base) ?? 0) + 1;
    used.set(base, count);
    const id = count === 1 ? base : `${base}-${count}`;
    const ja = line.ja ?? '';
    const th = line.th ?? undefined;
    return {
      id,
      video_id: videoId,
      line_index: i,
      start_time_ms: line.start_ms,
      end_time_ms: line.end_ms,
      raw_text: ja,
      natural_translation: '',
      thai_translation: th,
      ai_grammar_summary: '',
      tokens_json: ja ? buildTokens(id, ja, jlpt) : [],
    };
  });
};
